+/b37e/b37e/b3/f/r79ffv79vev+O//DwCF2uoAmAgA
__PROJECT_PAYLOAD__
tar -tzf "$PAYLOAD_FILE" >/dev/null || fail "The embedded project archive is invalid."
tar -xzf "$PAYLOAD_FILE" -C "$APP_ROOT" || fail "Could not install project files."
rm -f "$PAYLOAD_FILE"
trap - EXIT
TMUX_REAL="$(command -v tmux)"
TMUX_SOCKET="${TERMINAL_MANAGER_TMUX_SOCKET:-terminal-manager-$(id -u)}"
[[ "$TMUX_SOCKET" =~ ^[A-Za-z0-9_-]{1,64}$ ]] || fail "TERMINAL_MANAGER_TMUX_SOCKET must use 1-64 letters, digits, underscores, or hyphens."
TMUX_WRAPPER="$APP_ROOT/bin/tmux-manager"
printf '#!/usr/bin/env bash\nexec %q -L %q "$@"\n' "$TMUX_REAL" "$TMUX_SOCKET" > "$TMUX_WRAPPER"
chmod 700 "$TMUX_WRAPPER"

MODE="${TERMINAL_MANAGER_MODE:-}"
if [[ -z "$MODE" ]]; then
  [[ -r /dev/tty ]] || fail "Run interactively to choose Local or Cloudflare Tunnel mode, or set TERMINAL_MANAGER_MODE=local/cloudflare."
  printf 'Launch mode: [L]ocal or [C]loudflare Tunnel? [L]: ' > /dev/tty
  IFS= read -r MODE < /dev/tty || fail "Could not read the launch mode."
fi
case "${MODE,,}" in
  ""|l|local) MODE=local ;;
  c|cloudflare|"cloudflare tunnel") MODE=cloudflare ;;
  *) fail "Choose L for Local or C for Cloudflare Tunnel." ;;
esac
install_cloudflared() {
  command_exists cloudflared && return 0
  command_exists curl || fail "curl is required to install Cloudflare Tunnel from its official package repository."
  echo "Cloudflare Tunnel was selected; installing cloudflared from Cloudflare's official signed repository."
  if command_exists apt-get; then
    run_as_root install -d -m 0755 /usr/share/keyrings
    curl -fsSL https://pkg.cloudflare.com/cloudflare-main.gpg | run_as_root tee /usr/share/keyrings/cloudflare-main.gpg >/dev/null
    printf '%s\n' 'deb [signed-by=/usr/share/keyrings/cloudflare-main.gpg] https://pkg.cloudflare.com/cloudflared any main' | run_as_root tee /etc/apt/sources.list.d/cloudflared.list >/dev/null
    run_as_root apt-get update
    run_as_root apt-get install -y cloudflared
  elif command_exists dnf || command_exists yum; then
    run_as_root mkdir -p /etc/yum.repos.d
    curl -fsSL https://pkg.cloudflare.com/cloudflared.repo | run_as_root tee /etc/yum.repos.d/cloudflared.repo >/dev/null
    if command_exists dnf; then run_as_root dnf install -y cloudflared; else run_as_root yum install -y cloudflared; fi
  else
    fail "Automatic cloudflared installation is supported on Debian-based and RPM-based systems. On this Linux distribution, install cloudflared from https://developers.cloudflare.com/cloudflare-one/networks/connectors/cloudflare-tunnel/downloads/ or choose Local mode."
  fi
  command_exists cloudflared || fail "cloudflared installation failed; install it from Cloudflare's official downloads page or choose Local mode."
}
if [[ "$MODE" == cloudflare ]]; then
  install_cloudflared
fi

PORT="${TERMINAL_MANAGER_PORT:-0}"
[[ "$PORT" =~ ^[0-9]{1,5}$ ]] || fail "TERMINAL_MANAGER_PORT must be an integer from 0 to 65535."
if (( 10#$PORT > 65535 )); then fail "TERMINAL_MANAGER_PORT must be from 0 to 65535."; fi
[[ -f "$APP_ROOT/ccode.sh" ]] || fail "The control script is missing from the installation."
chmod 700 "$APP_ROOT/ccode.sh"
# The panel runs detached in the background; this terminal is released and the
# final output is the URL (and password) printed by ccode.sh.
exec bash "$APP_ROOT/ccode.sh" launch "$MODE" "$PORT"
